	}

	if s.DisableTools {
		batch, skipErr := s.disabledToolCalls(ctx, st.runID, opts, st.messages, pendingToolCalls)
		if skipErr != nil {
			s.emit(newErrorEvent(meta, skipErr.Error()))
			return skipErr
