func extractPackagePaths(goSourceCode string) []string {
	var packagePaths []string
	re := regexp.MustCompile(`import\s*\(\s*([^)]+)\s*\)`)
	matches := re.FindStringSubmatch(goSourceCode)
	if len(matches) > 1 {
		importBlock := matches[1]
		imports := strings.Split(importBlock, "\n")
		for _, imp := range imports {
			imp = strings.TrimSpace(imp)
			if imp != "" {
				packagePaths = append(packagePaths, strings.Trim(imp, `"`))
			}
		}
	} else {
		re = regexp.MustCompile(`import\s+"([^"]+)"`)
		matches = re.FindStringSubmatch(goSourceCode)
		for _, match := range matches {
			packagePaths = append(packagePaths, match)
		}
	}
	return packagePaths
}

